export const N=32;
export const STYLES={
 heritage:{name:'Old town',wall:'#cebda5',roof:'#835343',floors:3,roofType:'gable'},
 coastal:{name:'Coastal',wall:'#e3ddc9',roof:'#b97854',floors:2,roofType:'gable'},
 modern:{name:'Modern',wall:'#c5c9c3',roof:'#59676b',floors:5,roofType:'flat'},
 brick:{name:'Warehouse',wall:'#a67559',roof:'#636b69',floors:4,roofType:'flat'},
 nordic:{name:'Nordic',wall:'#aa6251',roof:'#48545c',floors:2,roofType:'gable'},
 japanese:{name:'Japanese',wall:'#d1c9b4',roof:'#535c60',floors:2,roofType:'pagoda'},
 mediterranean:{name:'Mediterranean',wall:'#dfcbb1',roof:'#ac6545',floors:3,roofType:'gable'},
 artdeco:{name:'Art deco',wall:'#d7c8a6',roof:'#6e7d78',floors:6,roofType:'stepped'},
 glass:{name:'Glass district',wall:'#73929a',roof:'#415762',floors:8,roofType:'flat'},
 garden:{name:'Garden city',wall:'#b7c0aa',roof:'#637553',floors:3,roofType:'garden'},
 industrial:{name:'Industrial',wall:'#a18d75',roof:'#596668',floors:4,roofType:'flat'},
 neon:{name:'Neon district',wall:'#647382',roof:'#374958',floors:7,roofType:'flat',neon:true}
};
export const TERRAINS={coast:'Peninsula',island:'Island',river:'River valley'};
export const CATALOG={
 road:{name:'Road',cost:60,upkeep:1,description:'Connect blocks to the Town Hall road network.',key:'1',color:'#798087'},
 home:{name:'Homes',cost:320,upkeep:2,description:'Homes grow when connected to roads, power and water.',key:'2',color:'#c18362'},
 shop:{name:'Shops',cost:650,upkeep:6,jobs:32,description:'Local businesses create 32 jobs and bring in tax revenue.',key:'3',color:'#71939a'},
 industry:{name:'Workshop',cost:900,upkeep:9,jobs:55,description:'Create 55 jobs. Keep workshops away from homes.',key:'4',color:'#a38b72'},
 office:{name:'Offices',cost:1800,upkeep:16,jobs:90,description:'Offices create 90 professional jobs when connected to roads and utilities.',key:'O',color:'#7896a0'},
 park:{name:'Park',cost:250,upkeep:3,description:'Green space improves happiness within 5 blocks.',key:'5',color:'#719768'},
 power:{name:'Wind power',cost:1800,upkeep:20,radius:13,description:'Clean electricity for buildings within 13 blocks.',key:'6',color:'#a4b9b6'},
 water:{name:'Water',cost:1400,upkeep:15,radius:13,description:'Fresh water for buildings within 13 blocks.',key:'7',color:'#80a4b3'},
 school:{name:'School',cost:2200,upkeep:25,radius:8,description:'Education improves happiness within 8 blocks.',key:'8',color:'#c9aa75'},
 clinic:{name:'Clinic',cost:2400,upkeep:28,radius:8,description:'Healthcare improves happiness within 8 blocks.',key:'9',color:'#d6d9cb'},
 fire:{name:'Fire station',cost:2000,upkeep:23,radius:8,description:'Fire protection within 8 blocks. Improves resident confidence.',key:'F',color:'#b76e52'},
 police:{name:'Police',cost:1900,upkeep:22,radius:8,description:'Neighborhood safety within 8 blocks improves happiness.',key:'P',color:'#788f9e'},
 demolish:{name:'Bulldoze',cost:0,description:'Remove a building and reclaim 25% of its cost.',key:'B',color:'#bd915b'}
};
export function hash(x,y,s=0){const n=Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453;return n-Math.floor(n)}
export function land(x,y,terrain='coast'){
 if(x<2||y<2||x>=30||y>=30)return false;
 if(terrain==='island')return ((x-15.5)/14)**2+((y-15.5)/13.5)**2<1;
 if(terrain==='river'){const bank=6+Math.round(Math.sin(y*.24));return !(x>=4&&x<=bank)}
 return x>=3&&y>=3&&x<29&&y<28&&x+y<49&&!(x>23&&y>15)&&!(x<6&&y>22)&&!(y<5&&x>22);
}
export function newCity(terrain='coast'){
 if(!Object.hasOwn(TERRAINS,terrain))terrain='coast';
 const s={version:1,name:'New Port',terrain,taxRate:9,day:1,money:32000,history:[],grid:Array.from({length:N*N},(_,i)=>({type:null,pop:0,age:0,seed:hash(i%N,Math.floor(i/N)),style:'heritage',zone:null})),grants:[],happiness:75};
 const put=(x,y,type,pop=0)=>{if(land(x,y,terrain))Object.assign(s.grid[y*N+x],{type,pop,age:8,style:['heritage','coastal','brick','modern'][Math.floor(hash(x,y,44)*4)]})};
 for(let x=5;x<25;x++)for(const y of [10,15,20])put(x,y,'road');
 for(let y=6;y<24;y++)for(const x of [8,13,18,23])put(x,y,'road');
 put(15,14,'hall');put(16,14,'park');put(15,13,'park');
 for(let y=7;y<23;y++)for(let x=7;x<24;x++){
  const t=s.grid[y*N+x];if(t.type||!land(x,y,terrain))continue;
  if([[-1,0],[1,0],[0,-1],[0,1]].some(([a,b])=>at(s,x+a,y+b)?.type==='road')&&hash(x,y,3)>.38){const v=hash(x,y,7);put(x,y,v<.64?'home':v<.87?'shop':'park',v<.64?6+Math.floor(hash(x,y,8)*7):0)}
 }
 put(14,14,'power');put(14,13,'water');put(21,21,'industry');put(22,21,'industry');put(19,19,'school');put(17,14,'clinic');put(18,18,'fire');put(12,14,'police');return s;
}
export function at(s,x,y){return Number.isInteger(x)&&Number.isInteger(y)&&x>=0&&y>=0&&x<N&&y<N?s.grid[y*N+x]:null}
export function connected(s){const set=new Set(),queue=[];s.grid.forEach((t,i)=>{if(t.type==='hall'){const x=i%N,y=Math.floor(i/N);for(const[a,b]of [[1,0],[-1,0],[0,1],[0,-1]])if(at(s,x+a,y+b)?.type==='road')queue.push((y+b)*N+x+a)}});while(queue.length){const i=queue.pop();if(set.has(i))continue;set.add(i);const x=i%N,y=Math.floor(i/N);for(const[a,b]of [[1,0],[-1,0],[0,1],[0,-1]])if(at(s,x+a,y+b)?.type==='road'&&!set.has((y+b)*N+x+a))queue.push((y+b)*N+x+a)}return set}
function nearRoad(x,y,roads){return [[-1,0],[1,0],[0,-1],[0,1]].some(([a,b])=>x+a>=0&&x+a<N&&y+b>=0&&y+b<N&&roads.has((y+b)*N+x+a))}
export function serviced(s,x,y,type,radius,roads){const funding=s.funding?.[type]??100;return funding>0&&s.grid.some((t,i)=>t.type===type&&t.enabled!==false&&Math.hypot(i%N-x,Math.floor(i/N)-y)<=radius*Math.sqrt(funding/100)&&(!roads||type==='park'||nearRoad(i%N,Math.floor(i/N),roads)))}
export function status(s,x,y,roads=connected(s)){const t=at(s,x,y);return {road:nearRoad(x,y,roads),power:serviced(s,x,y,'power',13,roads),water:serviced(s,x,y,'water',13,roads),park:serviced(s,x,y,'park',5),school:serviced(s,x,y,'school',8,roads),clinic:serviced(s,x,y,'clinic',8,roads),fire:serviced(s,x,y,'fire',8,roads),police:serviced(s,x,y,'police',8,roads),polluted:serviced(s,x,y,'industry',3),capacity:t?.density==='low'?16:t?.density==='high'?96:t?.seed>.7?48:28}}
export function metrics(s){const roads=connected(s);let pop=0,jobs=0,upkeep=0,good=0,homes=0,businessTax=0,housing=0;const sectorIncome={home:0,shop:0,industry:0,office:0};const taxRate=s.taxRate??9;s.grid.forEach((t,i)=>{pop+=t.pop||0;upkeep+=t.enabled===false?0:((CATALOG[t.type]?.upkeep||0)+(t.type==='road'&&t.roadKind==='bridge'?2:0)+(t.type==='road'&&t.roadKind==='boulevard'?1:0))*(s.funding?.[t.type]??100)/100;if(t.type==='home'){homes++;const a=status(s,i%N,Math.floor(i/N),roads);housing+=a.capacity;good+=30+15*a.road+12*a.power+12*a.water+9*a.park+7*a.school+7*a.clinic+4*a.police+4*a.fire-15*a.polluted}if(CATALOG[t.type]?.jobs&&t.enabled!==false){const a=status(s,i%N,Math.floor(i/N),roads);if(a.road&&a.power&&a.water){jobs+=CATALOG[t.type].jobs;sectorIncome[t.type]+=(t.type==='office'?110:t.type==='shop'?45:65)*(s.zoneTaxes?.[t.type]??taxRate)/9}}});const happiness=Math.max(10,Math.min(99,Math.round((homes?good/homes:70)-(pop>jobs*2?10:0)-Math.max(0,(s.zoneTaxes?.home??taxRate)-9)*4)));upkeep=Math.round(upkeep);const residentialTax=Math.floor(pop*.65*(s.zoneTaxes?.home??taxRate)/9);sectorIncome.home=residentialTax;for(const k of ['shop','industry','office'])sectorIncome[k]=Math.floor(sectorIncome[k]);businessTax=sectorIncome.shop+sectorIncome.industry+sectorIncome.office;const loanPayment=s.loan?.daysLeft>0?Math.min(s.loan.remaining,1400):0;return {sectorIncome,loanPayment,pop,jobs,upkeep,happiness,residentialTax,businessTax,income:residentialTax+businessTax-upkeep-loanPayment,roads,homes,housing,demand:{home:Math.max(0,Math.min(100,Math.round((jobs*2-pop)/Math.max(100,jobs*2)*100))),shop:Math.max(0,Math.min(100,Math.round(pop/Math.max(1,jobs*2)*100))),industry:Math.max(0,Math.min(100,Math.round(pop/Math.max(1,jobs*2)*90)))}}}
export function zone(s,x,y,type,style='heritage',options={}){const t=at(s,x,y);if(!t||!land(x,y,s.terrain))return{error:'Zone dry land beside a connected road.'};if(!['home','shop','industry','office',null].includes(type))return{error:'Unknown district type.'};if(t.type)return{error:'Zone open blocks. Clear existing buildings first.'};if(type&&s.money<20)return{error:'Zoning costs $20 per block.'};if(t.zone===type)return{error:'This block already has that zone.'};t.zone=type;t.density=['low','medium','high'].includes(options.density)?options.density:'medium';t.style=Object.hasOwn(STYLES,style)?style:'heritage';if(type)s.money-=20;return{ok:true}}
export function tick(s){const m=metrics(s);s.day++;s.money+=m.income;if(s.loan?.daysLeft>0){s.loan.remaining-=m.loanPayment;s.loan.daysLeft--;if(s.loan.daysLeft===0)s.loan=null}s.happiness=m.happiness;const changed=[];let available=Math.max(0,m.jobs*2-m.pop);s.grid.forEach((t,i)=>{const x=i%N,y=Math.floor(i/N);if(t.zone&&!t.type&&s.day%3===0&&hash(x,y,s.day)>.55){const a=status(s,x,y,m.roads);if(a.road&&a.power&&a.water){t.type=t.zone;t.age=0;t.pop=0;t.enabled=true;changed.push(i)}}if(t.type!=='home')return;const a=status(s,x,y,m.roads);const old=t.pop;if(a.road&&a.power&&a.water&&m.happiness>45&&available>0){const n=Math.min(available,a.capacity-t.pop,2+Math.floor(t.seed*3));t.pop+=n;available-=n;t.age++}else if(!a.road||!a.power||!a.water)t.pop=Math.max(0,t.pop-2);if(Math.floor(old/18)!==Math.floor(t.pop/18)&&!changed.includes(i))changed.push(i)});const n=metrics(s);for(const goal of [750,1500,2500])if(n.pop>=goal&&!s.grants.includes(goal)){s.grants.push(goal);s.money+=3000;changed.grant=goal}(s.history??=[]).push({day:s.day,pop:n.pop,money:Math.floor(s.money),income:n.income});s.history=s.history.slice(-120);return changed}
export function build(s,x,y,type,style='heritage',options={}){if(!Object.hasOwn(CATALOG,type))return{error:'Choose a building tool first.'};const t=at(s,x,y);if(!t||(!land(x,y,s.terrain)&&!(type==='road'&&options.roadKind==='bridge')))return{error:'Build on dry land, or use the Bridge road type to cross water.'};if(t.type==='hall')return{error:'Town Hall is the heart of your city. Keep it connected.'};if(type==='demolish'){if(!t.type&&!t.zone)return{error:'This block is already empty.'};s.money+=Math.floor((t.paid??CATALOG[t.type]?.cost??0)*.25);Object.assign(t,{type:null,zone:null,pop:0,age:0,enabled:true});return{ok:true}}if(t.type)return{error:t.type===type?'Already built here.':'This block is occupied. Clear it with the bulldozer first.'};const roadKind=['street','boulevard','oneway','pedestrian','bridge'].includes(options.roadKind)?options.roadKind:'street',cost=type==='road'?{street:60,boulevard:140,oneway:70,pedestrian:90,bridge:180}[roadKind]:CATALOG[type].cost;if(s.money<cost)return{error:'Treasury is too low. Let tax income build up first.'};s.money-=cost;Object.assign(t,{enabled:true,paid:cost,roadKind:type==='road'?roadKind:null,density:['low','medium','high'].includes(options.density)?options.density:'medium',type,pop:0,age:0,zone:null,style:Object.hasOwn(STYLES,style)?style:'heritage'});return{ok:true}}
export function validateCity(s){
 if(!s||s.version!==1||typeof s.name!=='string'||!s.name.trim()||s.name.length>28||!Number.isFinite(s.money)||Math.abs(s.money)>1e12||!Number.isInteger(s.day)||s.day<1||s.day>1e8||!Array.isArray(s.grid)||s.grid.length!==N*N||!Array.isArray(s.grants)||new Set(s.grants).size!==s.grants.length||s.grants.some(n=>![750,1500,2500].includes(n)))throw Error('Invalid city file');
 const terrain=s.terrain??'coast';if(!Object.hasOwn(TERRAINS,terrain)||!Number.isFinite(s.taxRate??9)||(s.taxRate??9)<5||(s.taxRate??9)>18)throw Error('Invalid city settings');let halls=0;
 const grid=s.grid.map((t,i)=>{if(!t||!(t.type===null||t.type==='hall'||(Object.hasOwn(CATALOG,t.type)&&t.type!=='demolish'))||!Number.isFinite(t.seed)||t.seed<0||t.seed>=1||!Number.isInteger(t.pop)||t.pop<0||t.pop>96||!Number.isInteger(t.age)||t.age<0||t.age>1e8||((t.type||t.zone)&&!land(i%N,Math.floor(i/N),terrain)&&!(t.type==='road'&&t.roadKind==='bridge'))||(t.type!=='home'&&t.pop!==0)||![null,undefined,'home','shop','industry','office'].includes(t.zone)||(t.style!==undefined&&!Object.hasOwn(STYLES,t.style))||(t.density!==undefined&&!['low','medium','high'].includes(t.density))||(t.roadKind!==undefined&&t.roadKind!==null&&!['street','boulevard','oneway','pedestrian','bridge'].includes(t.roadKind))||(t.paid!==undefined&&(!Number.isFinite(t.paid)||t.paid<0||t.paid>1e6))||(t.enabled!==undefined&&typeof t.enabled!=='boolean'))throw Error('Invalid block');if(t.type==='hall')halls++;return{type:t.type,pop:t.pop,age:t.age,seed:t.seed,zone:t.zone??null,enabled:t.enabled!==false,style:t.style??'heritage',density:t.density,roadKind:t.roadKind,paid:t.paid}});
 if(halls!==1)throw Error('City needs one Town Hall');const zoneTaxes={},funding={};for(const k of ['home','shop','industry','office']){const v=s.zoneTaxes?.[k]??s.taxRate??9;if(!Number.isInteger(v)||v<5||v>18)throw Error('Invalid sector tax');zoneTaxes[k]=v}for(const k of ['road','power','water','park','school','clinic','fire','police']){const v=s.funding?.[k]??100;if(!Number.isInteger(v)||v<0||v>150)throw Error('Invalid service funding');funding[k]=v}let loan=null;if(s.loan){if(!Number.isInteger(s.loan.daysLeft)||s.loan.daysLeft<1||s.loan.daysLeft>20||!Number.isInteger(s.loan.remaining)||s.loan.remaining!==s.loan.daysLeft*1400)throw Error('Invalid loan');loan={daysLeft:s.loan.daysLeft,remaining:s.loan.remaining}}const history=Array.isArray(s.history)?s.history.slice(-120).filter(h=>h&&['day','pop','money','income'].every(k=>Number.isFinite(h[k]))):[];return{version:1,zoneTaxes,funding,loan,name:s.name.trim(),money:s.money,day:s.day,terrain,taxRate:s.taxRate??9,history,grid,grants:[...s.grants],happiness:Number.isFinite(s.happiness)?s.happiness:75};
}

export function takeLoan(s){if(s.loan?.daysLeft>0)return{error:'Repay the current city loan first.'};s.loan={remaining:28000,daysLeft:20};s.money+=25000;return{ok:true}}
export function toggleBuilding(s,x,y){const t=at(s,x,y);if(!t?.type||['road','hall','home'].includes(t.type))return{error:'This building cannot be switched off.'};t.enabled=t.enabled===false;return{ok:true}}
